+	"verify",
+	"review_diff",
+	"wrap_up",
+	"commit",
+] as const;
+export type CoreKind = (typeof CORE_KINDS)[number];
+
+/** Kinds gated on a capability and evidence. */
+export const GATED_KINDS = [
+	"check_ci",
+	"reply_review",
+	"update_issue",
+	"post_update",
+] as const;
+export type GatedKind = (typeof GATED_KINDS)[number];
