+	"failed",
+	"tool_error",
+	"completed_edits",
+	"completed_no_edits",
+] as const;
+export type CueCode = (typeof CUE_CODES)[number];
+
+/** FNV-1a 32-bit as eight hex chars: short, stable, token-safe ids. */
+export function fnv1a32(text: string): string {
+	let hash = FNV_OFFSET_BASIS;
